        this.totalAmount = event.totalAmount();
        this.status = OrderStatus.PENDING_PAYMENT;
        setAggregateId(event.aggregateId());
    }

    private void applyOrderConfirmed(OrderConfirmedEvent event) {
        this.status = OrderStatus.CONFIRMED;
    }

