    public OrderController(
        CommandHandler<PlaceOrderCommand> placeOrderHandler,
        QueryHandler<GetOrderQuery, OrderDto> getOrderHandler
    ) {
        this.placeOrderHandler = placeOrderHandler;
        this.getOrderHandler = getOrderHandler;
    }

