import java.util.concurrent.ConcurrentHashMap;

/**
 * In-memory implementation of PricingOutboxRepository.
 */
@Repository
public class InMemoryPricingOutboxRepository implements PricingOutboxRepository {

    private final Map<String, OutboxMessage> outbox = new ConcurrentHashMap<>();

    @Override
    public void save(List<DomainEvent> events) {
        events.forEach(event -> {
            String messageId = UUID.randomUUID().toString();
            OutboxMessage message = new OutboxMessage(
                messageId,
