package com.konasl.common.outbox;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.konasl.common.domain.DomainEvent;

import java.time.Instant;
import java.util.UUID;

/**
 * Represents an event stored in the outbox for reliable publishing.
 */
public class OutboxEvent {

    private final String id;
    private final String eventType;
    private final String aggregateId;
    private final String payload;
    private final Instant createdAt;
    private OutboxStatus status;
    private Instant publishedAt;

    public OutboxEvent(String id, String eventType, String aggregateId, String payload, 
                      Instant createdAt, OutboxStatus status, Instant publishedAt) {
        this.id = id;
        this.eventType = eventType;
        this.aggregateId = aggregateId;
        this.payload = payload;
        this.createdAt = createdAt;
        this.status = status;
        this.publishedAt = publishedAt;
    }

    /**
     * Creates an OutboxEvent from a DomainEvent.
     *
     * @param event the domain event
     * @param objectMapper the JSON object mapper
     * @return the outbox event
     */
    public static OutboxEvent fromDomainEvent(DomainEvent event, ObjectMapper objectMapper) {
        try {
            String payload = objectMapper.writeValueAsString(event);
            return new OutboxEvent(
                UUID.randomUUID().toString(),
                event.getClass().getSimpleName(),
                event.getAggregateId(),
                payload,
                event.occurredOn(),
                OutboxStatus.PENDING,
                null
            );
        } catch (JsonProcessingException e) {
            throw new RuntimeException("Failed to serialize domain event", e);
        }
    }

    public void markAsPublished() {
        this.status = OutboxStatus.PUBLISHED;
        this.publishedAt = Instant.now();
    }

    // Getters
    public String getId() { return id; }
    public String getEventType() { return eventType; }
    public String getAggregateId() { return aggregateId; }
    public String getPayload() { return payload; }
    public Instant getCreatedAt() { return createdAt; }
    public OutboxStatus getStatus() { return status; }
    public Instant getPublishedAt() { return publishedAt; }
}
````

