# Find all Java processes running Spring Boot applications
$javaProcesses = Get-Process java -ErrorAction SilentlyContinue | Where-Object {
    $_.CommandLine -like "*spring-boot*" -or 
    $_.CommandLine -like "*bootRun*" -or
    $_.MainWindowTitle -like "*Service - Port*"
}

if ($javaProcesses.Count -eq 0) {
    Write-Host "No running services found." -ForegroundColor Yellow
    exit 0
}

Write-Host "Found $($javaProcesses.Count) running service(s):" -ForegroundColor Yellow
Write-Host ""

foreach ($process in $javaProcesses) {
    Write-Host "  - Stopping PID $($process.Id): $($process.MainWindowTitle)" -ForegroundColor White
    Stop-Process -Id $process.Id -Force
}

Write-Host ""
Write-Host "All services stopped successfully." -ForegroundColor Green
